effect.shader:

void main() {
    vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);

    float distance = 1 - texColor.g;
    if(!onlyCoarse) {
        distance += (texColor.r + texColor.b)/2/255;
    }
    distance *= 5.0;

    float lum = clamp((distance - clipLow) / (clipHigh - clipLow), 0.0,1.0);
    gl_FragColor = vec4(lum, lum, lum, 1.0);
}
